	SELLER_LEI VARCHAR2(100),
	SELLER_NAME VARCHAR2(200),
	TRADE_FLAG VARCHAR2(50),
	REGULATORY_FLAG VARCHAR2(50),
	PRICE_DEVIATION_BPS NUMBER(10,4),
	SLIPPAGE_BPS NUMBER(10,4),
	ADDITIONAL_DATA CLOB,
	RAW_PAYLOAD CLOB,
	 PRIMARY KEY (ID) ENABLE
   )
/

-- Table: PRE_TRADE
CREATE TABLE PRE_TRADE
   (	ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	MESSAGE_ID VARCHAR2(100),
	TOPIC VARCHAR2(100),
	RECEIVED_AT TIMESTAMP (6) DEFAULT SYSTIMESTAMP,
	MESSAGE_TYPE VARCHAR2(20),
	RIC VARCHAR2(50),
	CURRENCY_PAIR VARCHAR2(20),
	TIMESTAMP_VAL TIMESTAMP (6),
	SOURCE VARCHAR2(100),
	VENUE VARCHAR2(100),
	MARKET_SESSION VARCHAR2(20),
	TRANSACTION_ID VARCHAR2(100),
	BID_PRICE NUMBER(20,8),
	ASK_PRICE NUMBER(20,8),
	MID_PRICE NUMBER(20,8),
	VOLUME NUMBER(20,4),
	DATA_TYPE VARCHAR2(50),
	BEST_BID NUMBER(20,8),
	BEST_ASK NUMBER(20,8),
	SPREAD NUMBER(20,8),
	SPREAD_BPS NUMBER(10,4),
	BID_SIZE NUMBER(20,4),
	ASK_SIZE NUMBER(20,4),
	IMBALANCE_RATIO NUMBER(10,6),
	INDICATIVE VARCHAR2(10),
	FEED_STATUS VARCHAR2(50),
	BID_DEPTH CLOB,
	ASK_DEPTH CLOB,
	ADDITIONAL_DATA CLOB,
	RAW_PAYLOAD CLOB,
	 PRIMARY KEY (ID) ENABLE
   )
/

-- Table: PROMOTION_APPROVALS
CREATE TABLE PROMOTION_APPROVALS
   (	ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	REQUEST_ID NUMBER NOT NULL ENABLE,
	APPROVAL_LEVEL NUMBER(2,0) NOT NULL ENABLE,
	APPROVER_USER VARCHAR2(100) NOT NULL ENABLE,
	ACTION VARCHAR2(20) NOT NULL ENABLE,
	ACTIONED_AT TIMESTAMP (6) DEFAULT SYSTIMESTAMP,
	COMMENTS VARCHAR2(1000),
	 PRIMARY KEY (ID) ENABLE,
	 CONSTRAINT FK_PROMO_APPROVAL_REQ FOREIGN KEY (REQUEST_ID)
	  REFERENCES PROMOTION_REQUESTS (ID) ENABLE
   )
/

-- Table: PROMOTION_REQUESTS
CREATE TABLE PROMOTION_REQUESTS
   (	ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	TOPIC_NAME VARCHAR2(200) NOT NULL ENABLE,
	CURRENCY_PAIR VARCHAR2(20) NOT NULL ENABLE,
	PARTITION_DATE VARCHAR2(10) NOT NULL ENABLE,
	PARTITION_HOUR NUMBER(2,0) NOT NULL ENABLE,
	REQUESTED_BY VARCHAR2(100) NOT NULL ENABLE,
	REQUESTED_AT TIMESTAMP (6) DEFAULT SYSTIMESTAMP,
	STATUS VARCHAR2(20) DEFAULT 'PENDING',
	CURRENT_LEVEL NUMBER(2,0) DEFAULT 1,
	TOTAL_LEVELS NUMBER(2,0) DEFAULT 2,
	NOTES CLOB,
	 PRIMARY KEY (ID) ENABLE
   )
/

-- Table: TOPIC_CONFIGURATIONS
CREATE TABLE TOPIC_CONFIGURATIONS
   (	ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	TOPIC_NAME VARCHAR2(255) NOT NULL ENABLE,
	DESCRIPTION VARCHAR2(500) NOT NULL ENABLE,
	BOOTSTRAP_SERVERS VARCHAR2(500) NOT NULL ENABLE,
	GROUP_ID VARCHAR2(255) NOT NULL ENABLE,
	SSL_ENABLED NUMBER(1,0) DEFAULT 1,
	TRUSTSTORE_LOCATION VARCHAR2(500),
	TRUSTSTORE_PASSWORD VARCHAR2(255),
	KEYSTORE_LOCATION VARCHAR2(500),
	KEYSTORE_PASSWORD VARCHAR2(255),
	KEY_PASSWORD VARCHAR2(255),
	SECURITY_PROTOCOL VARCHAR2(50) DEFAULT 'SSL',
	AUTO_OFFSET_RESET VARCHAR2(50) DEFAULT 'earliest',
	MAX_POLL_RECORDS NUMBER DEFAULT 500,
	SESSION_TIMEOUT_MS NUMBER DEFAULT 30000,
	STATUS VARCHAR2(50) DEFAULT 'INACTIVE' NOT NULL ENABLE,
	CREATED_AT TIMESTAMP (6) DEFAULT CURRENT_TIMESTAMP NOT NULL ENABLE,
	UPDATED_AT TIMESTAMP (6),
	CREATED_BY VARCHAR2(255),
	UPDATED_BY VARCHAR2(255),
	SSL_PROTOCOL VARCHAR2(20) DEFAULT 'TLSv1.3',
	SSL_ENDPOINT_IDENTIFICATION_ALGORITHM VARCHAR2(50) DEFAULT 'https',
	TRUSTSTORE_TYPE VARCHAR2(20) DEFAULT 'PEM',
	SSL_TRUSTSTORE_LOCATION VARCHAR2(500),
	SASL_MECHANISM VARCHAR2(50) DEFAULT 'PLAIN',
	SASL_JAAS_CONFIG CLOB,
	DEDUP_ENABLED NUMBER(1,0) DEFAULT 0,
	DEDUP_WINDOW_SECONDS NUMBER(10,0) DEFAULT 300,
	DEDUP_KEY_FIELDS CLOB,
	PAIR_FIELDS CLOB,
	MESSAGE_SCHEMA CLOB,
	ERROR_TOPIC_BOOTSTRAP_SERVERS VARCHAR2(500),
	ERROR_TOPIC_SECURITY_PROTOCOL VARCHAR2(50),
	ERROR_TOPIC_SASL_MECHANISM VARCHAR2(50),
	ERROR_TOPIC_SASL_JAAS_CONFIG CLOB,
	ERROR_TOPIC_SSL_TRUSTSTORE_LOCATION VARCHAR2(500),
	ERROR_TOPIC_TRUSTSTORE_TYPE VARCHAR2(20),
	 CONSTRAINT CHK_TOPIC_SSL CHECK (ssl_enabled IN (0, 1)) ENABLE,
	 CONSTRAINT CHK_TOPIC_STATUS CHECK (status IN ('ACTIVE', 'INACTIVE', 'ERROR')) ENABLE,
	 PRIMARY KEY (ID) ENABLE,
	 UNIQUE (TOPIC_NAME) ENABLE
   )
/

-- Table: USERS
CREATE TABLE USERS
   (	USER_ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	USERNAME VARCHAR2(100) NOT NULL ENABLE,
	EMAIL VARCHAR2(255) NOT NULL ENABLE,
	FULL_NAME VARCHAR2(255),
	PASSWORD_HASH VARCHAR2(255),
	IS_ADMIN NUMBER(1,0) DEFAULT 0,
	IS_ACTIVE NUMBER(1,0) DEFAULT 1,
	CREATED_AT TIMESTAMP (6) DEFAULT CURRENT_TIMESTAMP,
	UPDATED_AT TIMESTAMP (6) DEFAULT CURRENT_TIMESTAMP,
	ROLE VARCHAR2(50) DEFAULT 'VIEWER',
	DEPARTMENT VARCHAR2(100),
	LAST_LOGIN TIMESTAMP (6),
	 CONSTRAINT CHK_USER_ADMIN CHECK (is_admin IN (0, 1)) ENABLE,
	 CONSTRAINT CHK_USER_ACTIVE CHECK (is_active IN (0, 1)) ENABLE,
	 PRIMARY KEY (USER_ID) ENABLE,
	 UNIQUE (USERNAME) ENABLE,
	 UNIQUE (EMAIL) ENABLE
   )
/

-- Table: USER_ATTRIBUTE_GRANTS
CREATE TABLE USER_ATTRIBUTE_GRANTS
   (	ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	USER_ID NUMBER NOT NULL ENABLE,
	TOPIC_NAME VARCHAR2(200) NOT NULL ENABLE,
	FIELD_NAME VARCHAR2(200) NOT NULL ENABLE,
	GRANTED_BY NUMBER,
	GRANTED_AT TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
	 PRIMARY KEY (ID)  ENABLE,
	 CONSTRAINT UQ_ATTR_GRANT UNIQUE (USER_ID, TOPIC_NAME, FIELD_NAME)  ENABLE,
	 CONSTRAINT FK_AG_USER FOREIGN KEY (USER_ID)
	  REFERENCES USERS (USER_ID) ON DELETE CASCADE ENABLE,
	 CONSTRAINT FK_AG_GRANTER FOREIGN KEY (GRANTED_BY)
	  REFERENCES USERS (USER_ID) ON DELETE SET NULL ENABLE
   )
/

-- Table: USER_CHART_SETTINGS
CREATE TABLE USER_CHART_SETTINGS
   (	SETTING_ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	USER_ID NUMBER NOT NULL ENABLE,
	SETTING_NAME VARCHAR2(255) NOT NULL ENABLE,
	CHART_TYPE VARCHAR2(50) DEFAULT 'candlestick',
	CURRENCY_PAIRS VARCHAR2(1000),
	TIMEFRAME VARCHAR2(50) DEFAULT '1h',
	THEME VARCHAR2(50) DEFAULT 'dark',
	CHART_CONFIG_JSON CLOB,
	IS_DEFAULT NUMBER(1,0) DEFAULT 0,
	CREATED_AT TIMESTAMP (6) DEFAULT CURRENT_TIMESTAMP,
	UPDATED_AT TIMESTAMP (6) DEFAULT CURRENT_TIMESTAMP,
	 CONSTRAINT CHK_CHART_DEFAULT CHECK (is_default IN (0, 1)) ENABLE,
	 PRIMARY KEY (SETTING_ID) ENABLE,
	 CONSTRAINT UK_USER_SETTING UNIQUE (USER_ID, SETTING_NAME) ENABLE,
	 CONSTRAINT FK_CHART_USER FOREIGN KEY (USER_ID)
	  REFERENCES USERS (USER_ID) ON DELETE CASCADE ENABLE
   )
/

-- Table: USER_PAIR_CATALOG
CREATE TABLE USER_PAIR_CATALOG
   (	ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	TOPIC_NAME VARCHAR2(200) NOT NULL ENABLE,
	DATA_TYPE VARCHAR2(50) NOT NULL ENABLE,
	SOURCE VARCHAR2(200) NOT NULL ENABLE,
	PAIR VARCHAR2(50) NOT NULL ENABLE,
	FIRST_SEEN TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
	LAST_SEEN TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
	 PRIMARY KEY (ID)  ENABLE,
	 CONSTRAINT UQ_PAIR_CATALOG UNIQUE (TOPIC_NAME, DATA_TYPE, SOURCE, PAIR)  ENABLE
   )
/

-- Table: USER_PAIR_GRANTS
CREATE TABLE USER_PAIR_GRANTS
   (	ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	USER_ID NUMBER NOT NULL ENABLE,
	GRANT_LEVEL VARCHAR2(10) NOT NULL ENABLE,
	DATA_TYPE VARCHAR2(50) NOT NULL ENABLE,
	SOURCE VARCHAR2(200),
	PAIR VARCHAR2(50),
	GRANTED_BY NUMBER,
	GRANTED_AT TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
	 CONSTRAINT CHK_GRANT_LEVEL CHECK (grant_level IN ('TYPE','SOURCE','PAIR')) ENABLE,
	 PRIMARY KEY (ID)  ENABLE,
	 CONSTRAINT UQ_PAIR_GRANT UNIQUE (USER_ID, GRANT_LEVEL, DATA_TYPE, SOURCE, PAIR)  ENABLE,
	 CONSTRAINT FK_PG_USER FOREIGN KEY (USER_ID)
	  REFERENCES USERS (USER_ID) ON DELETE CASCADE ENABLE,
	 CONSTRAINT FK_PG_GRANTER FOREIGN KEY (GRANTED_BY)
	  REFERENCES USERS (USER_ID) ON DELETE SET NULL ENABLE
   )
/

-- Table: VALIDATION_RULES
CREATE TABLE VALIDATION_RULES
   (	ID NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1  NOT NULL ENABLE,
	TOPIC_NAME VARCHAR2(200) NOT NULL ENABLE,
	RULE_NAME VARCHAR2(100) NOT NULL ENABLE,
	FIELD_NAME VARCHAR2(100) NOT NULL ENABLE,
	OPERATOR VARCHAR2(20) NOT NULL ENABLE,
	THRESHOLD_VALUE VARCHAR2(200),
	ACTIVE NUMBER(1,0) DEFAULT 1,
	SEVERITY VARCHAR2(10) DEFAULT 'WARN',
	ACTION VARCHAR2(20) DEFAULT 'LOG',
	CREATED_AT TIMESTAMP (6) DEFAULT SYSTIMESTAMP,
	DESCRIPTION VARCHAR2(500),
	CUSTOM_EXPRESSION VARCHAR2(1000),
	 PRIMARY KEY (ID) ENABLE
   )
/

